const sourceAudit = auditCom003OfficeTabsSources();
if (!sourceAudit.valid) throw new Error(`COM-003 Office tabs source audit failed: ${sourceAudit.issues.join(", ")}`);
const validQlIds = new Set(COM003_OFFICE_TABS_QLS.map((item) => item.qlId));
const sourceIds = new Set(COM003_OFFICE_TABS_SOURCE_AUTHORITIES.map((item) => item.sourceId));

export type Com003OfficeTabsQuestion = {
  questionId: string;
  sourceQuestionId: string;
  localizationId: string;
  qlId: string;
  cpId: "COM-003-CP-002";
  language: Com003OfficeTabsLanguage;
  locale: "en-IN" | "hi-IN" | "pa-IN";
  surfaceMode: string;
  examSurfaceFamily: Com003OfficeTabsFamily;
  targetFactId: string;
  stem: string;
  options: readonly string[];
  correctIndex: number;
  canonicalAnswer: string;
  explanation: string;
  sourceIds: readonly string[];
  sourceFactIds: readonly string[];
  difficulty: Com003OfficeTabsDifficulty;
  versionScoped: true;
  sourceEnglishFrozen: true;
  sourceLocalizationFrozen: false;
  reviewOnly: true;
  runtimeRegistered: false;
};

function materialize(language: Com003OfficeTabsLanguage): readonly Com003OfficeTabsQuestion[] {
  const locale = language === "en" ? "en-IN" : language === "hi" ? "hi-IN" : "pa-IN";
  return D.map((definition, index) => {
    const ql = qlById.get(definition.qlId);
    if (!ql) throw new Error(`Missing Office tabs QL metadata for ${definition.qlId}`);
    const copy = definition[language];
    if (copy.options.length !== 4 || copy.options[definition.correctIndex] !== copy.canonicalAnswer) {
      throw new Error(`Invalid Office tabs answer position ${definition.targetFactId}/${language}`);
    }
    return {
      questionId: `COM003-OFFICE-TABS-${String(index + 1).padStart(3, "0")}`,
      sourceQuestionId: `COM003-OFFICE-TABS-${String(index + 1).padStart(3, "0")}`,
      localizationId: `COM003-OFFICE-TABS-${language.toUpperCase()}-${String(index + 1).padStart(3, "0")}`,
      qlId: definition.qlId,
      cpId: "COM-003-CP-002",
      language,
      locale,
      surfaceMode: definition.surfaceMode,
      examSurfaceFamily: definition.examSurfaceFamily,
      targetFactId: definition.targetFactId,
      stem: copy.stem,
      options: copy.options,
      correctIndex: definition.correctIndex,
      canonicalAnswer: copy.canonicalAnswer,
      explanation: copy.explanation,
      sourceIds: ql.sourceIds,
      sourceFactIds: [definition.targetFactId],
      difficulty: definition.difficulty,
      versionScoped: true,
      sourceEnglishFrozen: true,
      sourceLocalizationFrozen: false,
      reviewOnly: true,
      runtimeRegistered: false,
    };
  });
}

export const COM003_OFFICE_TABS_ENGLISH_REVIEW = materialize("en");
export const COM003_OFFICE_TABS_HINDI_REVIEW = materialize("hi");
export const COM003_OFFICE_TABS_PUNJABI_REVIEW = materialize("pa");

export const COM003_OFFICE_TABS_AUTHORITY_V1 = Object.freeze({
  authorityId: "COM-003-OFFICE-TABS-COMPLETION-V1" as const,
  packageId: "COM-003-OFFICE-TABS" as const,
  chapterCode: "COM-003" as const,
  cpId: "COM-003-CP-002" as const,
  status: "REVIEW_ONLY" as const,
  scope: "Exam-relevant Excel and PowerPoint interface and Ribbon tab functionality for the standard desktop Office surface." as const,
  permanentQlIds: Object.freeze(COM003_OFFICE_TABS_QLS.map((item) => item.qlId)),
  qlCount: COM003_OFFICE_TABS_QLS.length,
  questionsPerQlPerLanguage: 8,
  questionCountPerLanguage: COM003_OFFICE_TABS_ENGLISH_REVIEW.length,
  supportedLanguages: Object.freeze(["en", "hi", "pa"] as const),
  englishQuestionCount: COM003_OFFICE_TABS_ENGLISH_REVIEW.length,
  hindiQuestionCount: COM003_OFFICE_TABS_HINDI_REVIEW.length,
  punjabiQuestionCount: COM003_OFFICE_TABS_PUNJABI_REVIEW.length,
  totalQuestionLanguageArtifacts: COM003_OFFICE_TABS_ENGLISH_REVIEW.length + COM003_OFFICE_TABS_HINDI_REVIEW.length + COM003_OFFICE_TABS_PUNJABI_REVIEW.length,
  versionScoped: true,
  hardDifficultyAuthorized: false,
  questionBankAcceptanceMode: "REQUIRES_USER_APPROVAL_THEN_BANK_ONLY" as const,
  questionStudioRuntimeAuthorized: true,
  questionBankWritesAuthorized: false,
  testEligible: false,
  mockTestEligible: false,
  publiclyPublishable: false,
  productionReleaseAuthorized: false,
});

export function auditCom003OfficeTabsCompletion() {
  const issues: string[] = [];
  if (D.length !== COM003_OFFICE_TABS_QLS.length * 8) issues.push(`ENGLISH_COUNT:${D.length}`);
  for (const ql of COM003_OFFICE_TABS_QLS) {
    const questions = D.filter((item) => item.qlId === ql.qlId);
    if (questions.length !== 8) issues.push(`QL_COUNT:${ql.qlId}:${questions.length}`);
    for (const question of questions) {
      if (!validQlIds.has(question.qlId)) issues.push(`UNKNOWN_QL:${question.qlId}`);
      if (!ql.sourceIds.every((sourceId) => sourceIds.has(sourceId))) issues.push(`UNKNOWN_SOURCE:${ql.qlId}`);
      if (question.en.options.length !== 4 || question.hi.options.length !== 4 || question.pa.options.length !== 4) issues.push(`OPTION_COUNT:${question.targetFactId}`);
      if (question.en.options[question.correctIndex] !== question.en.canonicalAnswer) issues.push(`EN_ANSWER:${question.targetFactId}`);
      if (question.hi.options[question.correctIndex] !== question.hi.canonicalAnswer) issues.push(`HI_ANSWER:${question.targetFactId}`);
      if (question.pa.options[question.correctIndex] !== question.pa.canonicalAnswer) issues.push(`PA_ANSWER:${question.targetFactId}`);
      if (!question.en.stem.trim() || !question.hi.stem.trim() || !question.pa.stem.trim()) issues.push(`EMPTY_STEM:${question.targetFactId}`);
      if (!question.en.explanation.trim() || !question.hi.explanation.trim() || !question.pa.explanation.trim()) issues.push(`EMPTY_EXPLANATION:${question.targetFactId}`);
      if (/^(?:based on|in the following|according to|as per)\b/i.test(question.en.stem)) issues.push(`FILLER_STEM:${question.targetFactId}`);
    }
  }
  const ids = [COM003_OFFICE_TABS_ENGLISH_REVIEW, COM003_OFFICE_TABS_HINDI_REVIEW, COM003_OFFICE_TABS_PUNJABI_REVIEW].map((items) => items.map((item) => item.sourceQuestionId).join("|"));
  if (!(ids[0] === ids[1] && ids[1] === ids[2])) issues.push("LANGUAGE_PARITY");
  return {
    valid: issues.length === 0,
    qls: COM003_OFFICE_TABS_QLS.length,
    questionsPerLanguage: COM003_OFFICE_TABS_ENGLISH_REVIEW.length,
    totalQuestionLanguageArtifacts: COM003_OFFICE_TABS_AUTHORITY_V1.totalQuestionLanguageArtifacts,
    issues,
  };
}

export const COM003_OFFICE_TABS_COMPLETION_AUDIT_V1 = auditCom003OfficeTabsCompletion();
if (!COM003_OFFICE_TABS_COMPLETION_AUDIT_V1.valid) {
  throw new Error(`COM-003 Office tabs completion audit failed: ${COM003_OFFICE_TABS_COMPLETION_AUDIT_V1.issues.join(", ")}`);
}
